ratings = [
    {"query_id": "q1", "reviewer": "r1", "helpfulness": 4, "tone": 5},
    {"query_id": "q1", "reviewer": "r2", "helpfulness": 4, "tone": 4},
    {"query_id": "q2", "reviewer": "r1", "helpfulness": 2, "tone": 3},
    {"query_id": "q2", "reviewer": "r2", "helpfulness": 3, "tone": 3},
]

def average_by_query(ratings, field):
    # average ratings for the same query across reviewers
    by_query = {}
    for r in ratings:
        by_query.setdefault(r["query_id"], []).append(r[field])
    return {q: sum(scores) / len(scores) for q, scores in by_query.items()}

def inter_rater_agreement(ratings, field, tolerance=1):
    # check how closely reviewers agree per query
    by_query = {}
    for r in ratings:
        by_query.setdefault(r["query_id"], []).append(r[field])
    agreements = [max(scores) - min(scores) <= tolerance for scores in by_query.values()]
    return sum(agreements) / len(agreements)

print("Average helpfulness by query:")
print(average_by_query(ratings, "helpfulness"))

agreement = inter_rater_agreement(ratings, "helpfulness")
print(f"\nInter-rater agreement on helpfulness: {agreement:.2f}")
